<?php
declare(strict_types=1);require_once __DIR__.'/includes/functions.php';$q=trim($_GET['q']??'');$posts=[];if($q!==''){$s=db()->prepare("SELECT p.*,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='published' AND p.published_at<=NOW() AND (p.title LIKE :q OR p.excerpt LIKE :q OR p.content LIKE :q) ORDER BY p.published_at DESC LIMIT 50");$s->execute([':q'=>'%'.$q.'%']);$posts=$s->fetchAll();}$pageTitle='Поиск — '.APP_NAME;include __DIR__.'/includes/header.php';?><h1 class="archive-heading">Поиск</h1><?php if($q===''):?><p>Введите запрос в строку поиска.</p><?php else:?><p><strong>Запрос:</strong> <?=e($q)?> · найдено: <?=count($posts)?></p><section class="story-grid"><?php foreach($posts as $p):?><article class="news-card"><span class="section-label"><?=e($p['category_name']??'Новости')?></span><h2><a href="<?=e(url('article.php?slug='.urlencode($p['slug'])))?>"><?=e($p['title'])?></a></h2><p><?=e($p['excerpt']?:excerpt($p['content']))?></p></article><?php endforeach;?></section><?php endif;?><?php include __DIR__.'/includes/footer.php';?>
